head.script:
scwin.onpageload = function() {

};

/**
 * @method
 * @name removeRow
 * @description DataCollection(dataList)의 지정 행을 삭제한다. (Gauce RemoveRow 호환 래퍼)
 * @param {Object} dataList 대상 DataList
 * @param {Number} idx 삭제할 행 인덱스
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.cp.removeRow(dlt_list, 0);
 */
scwin.removeRow = function(dataList,idx) {
    dataList.removeRow(idx);
};

/**
 * @method
 * @name isModified
 * @description DataCollection(단건 또는 배열)의 수정 여부를 반환한다. ($c.data.isModified 위임)
 * @param {Object} dcObjArr DataCollection 또는 배열
 * @returns {Boolean} 수정 여부
 * @hidden N
 * @exception
 * @example if ($c.cp.isModified([dlt_list, dma_req])) { ... }
 */
scwin.isModified = function(dcObjArr) {
    return $c.data.isModified(dcObjArr);
};

/**
 * @method
 * @name getNameValueRow
 * @description 컬럼 값이 일치하는 첫 행의 1-base 인덱스를 반환한다. (Gauce IndexOfColumn 호환 —
 * Gauce 행 번호 규약에 맞춰 1-base 로 반환하며, 일치 행이 없으면 0)
 * @param {Object} dataList 대상 DataList
 * @param {String} columnId 검색할 컬럼 ID
 * @param {String} value 찾을 값
 * @returns {Number} 일치하는 첫 행의 1-base 인덱스 (없으면 0)
 * @hidden N
 * @exception
 * @example const idx = $c.cp.getNameValueRow(dlt_code, "CD_VAL", "01"); // 1-base
 */
scwin.getNameValueRow = function(dataList,columnId,value) {
    const matched = dataList.getMatchedIndex(columnId, value);
    return (matched.length > 0) ? matched[0] + 1 : 0;
};

/**
 * @method
 * @name nameMax
 * @description 지정 행 구간에서 컬럼 값의 최대값을 반환한다. (Gauce NameMax 호환)
 * @param {Object} dataList 대상 DataList
 * @param {String} columnId 컬럼 ID
 * @param {Number} fromRow 시작 행
 * @param {Number} toRow 종료 행
 * @returns {Number} 최대값
 * @hidden N
 * @exception
 * @example const max = $c.cp.nameMax(dlt_list, "col1", 0, dlt_list.getRowCount() - 1);
 */
scwin.nameMax = function(dataList,columnId, fromRow, toRow) {
    const distinctValues = dataList.getColumnDistinctDataArray(columnId, fromRow, toRow);
    return Math.max(...distinctValues);
};

/**
 * @method
 * @name getColumnProp
 * @description 그리드 컬럼 속성값을 반환한다. (Gauce 컬럼 속성 getter 호환 — setColumnProp 의 조회 쌍)
 * Show:표시 여부 / Width:너비(px) / Name:헤더 텍스트 / Edit:읽기전용 여부
 * @param {Object} grdObj 그리드뷰 컴포넌트
 * @param {String} columnId 컬럼 ID
 * @param {String} propertyName 속성명 (Show/Width/Name/Edit)
 * @returns {Object} 속성값 (지원하지 않는 속성명이면 undefined)
 * @hidden N
 * @exception
 * @example const visible = $c.cp.getColumnProp(grd_list, "col1", "Show");
 */
scwin.getColumnProp = function(grdObj,columnId,propertyName) {    //'Show'
    if (propertyName == "Show") {
        return grdObj.getColumnVisible(columnId);   //true, false
    } else if (propertyName == "Width") {
        return grdObj.getColumnWidth(columnId); //Number Width Pixel
    } else if (propertyName == "Name") {
        return grdObj.getHeaderValue(columnId); //header text value
    } else if (propertyName == "Edit") {
        return grdObj.getColumnReadOnly(columnId); //any, none
    }
};

/**
 * @method
 * @name setColumnProp
 * @description 그리드 컬럼 속성값을 설정한다. (Gauce 컬럼 속성 setter 호환)
 * Show:표시 여부 / Width:너비(px) / Name:헤더 텍스트 / Edit:읽기전용 여부
 * @param {Object} grdObj 그리드뷰 컴포넌트
 * @param {String} columnId 컬럼 ID
 * @param {String} propertyName 속성명 (Show/Width/Name/Edit)
 * @param {Object} propertyValue 설정할 속성값
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.cp.setColumnProp(grd_list, "col1", "Show", false);
 */
scwin.setColumnProp = function(grdObj,columnId,propertyName,propertyValue) {   //'Show',true
    //mask 4, headchkeck 22, data 20, Suppress 11, Multiline 14,
    if (propertyName == "Show") {
        grdObj.setColumnVisible(columnId, propertyValue);   //true, false
    } else if (propertyName == "Width") {
        grdObj.setColumnWidth(columnId, propertyValue); //Number Width Pixel
    } else if (propertyName == "Name") {
        grdObj.setHeaderValue(columnId, propertyValue); //header text value
    } else if (propertyName == "Edit") {
        grdObj.setColumnReadOnly(columnId, propertyValue); //any, none
    }
};

/**
 * @method
 * @name setBroadCast
 * @description 그리드뷰의 dataCollection 동기화를 제어한다
 * @param {Object} grdObj 그리드뷰 컴포넌트
 * @param {Boolean} useYn 사용여부
 * @hidden N
 * @exception
 * @example
 *      $c.cp.setBroadCast(grd_list, false);
 *      dlt_list.setJSON(jsonData);
 *      $c.cp.setBroadCast(grd_list, true);
 */ 
scwin.setBroadCast = function(grdObj,useYn) {
    const dltObj = $p.getComponentById(grdObj.getDataList());
    dltObj.setBroadcast(useYn);
};

/**
 * @method
 * @name valueOfIndex
 * @description 셀렉트박스에서 지정 컬럼의 값을 반환한다. (Gauce ValueOfIndex 호환)
 * 요청 컬럼(value)이 itemset 의 value 컬럼이면 선택된 값(getValue)을, 그 외에는 선택 인덱스를 반환한다.
 * @param {Object} selectboxObj 셀렉트박스 컴포넌트
 * @param {String} value 조회할 itemset 컬럼명 (예: "VALUE")
 * @param {Number} index 조회할 인덱스 (현재 구현은 선택 상태 기준)
 * @returns {String} 선택된 값 (value 컬럼이 아니면 선택 인덱스)
 * @hidden N
 * @exception
 * @example dlt.setCellData(1, "CD", $c.cp.valueOfIndex(cb_gbn, "VALUE", cb_gbn.getSelectedIndex()));
 */
scwin.valueOfIndex = function(selectboxObj,value,index) {
    if (selectboxObj.itemsetObj.value == value) {
        return selectboxObj.getValue();
    }
    return selectboxObj.getSelectedIndex();
};
